class Solution {
public:
    int canBeTypedWords(string text, string brokenLetters) {
        bool broken[26] = {false};
        for (char c : brokenLetters) {
            broken[c - 'a'] = true;
        }
        int count = 0;
        int n = text.size();
        int i = 0;
        while (i < n) {
            bool typeable = true;
            while (i < n && text[i] != ' ') {
                if (broken[text[i] - 'a']) {
                    typeable = false;
                }
                i++;
            }
            if (typeable) {
                count++;
            }
            i++; // skip the space
        }
        return count;
    }
};
